from pathlib import Path
import base64, gzip, hashlib, json
for item in [{'path': '/marimo/results/rq2/minimal_pairs_v3/inputs/prompts.jsonl', 'sha256': 'dffff8f6a45f3abaf69c2b5f291952d940a3539debadd4e52108d9a923b3cd9b', 'data': ''}, {'path': '/marimo/results/rq2/minimal_pairs_v3/inputs/pairs.json', 'sha256': '79d087372d9a0659f3ec9011297a034a4bd7532fc596383c432e9fec9aa48671', 'data': ''}, {'path': '/marimo/domains/menu_planning/scripts/minimal_pairs/audited_helper.py', 'sha256': 'eebf94601bb21248b1279119bede2e65c4f6c5ea3399033512996e5b42a8f174', 'data': ''}, {'path': '/marimo/domains/menu_planning/scripts/minimal_pairs/extract_minimal_pairs.py', 'sha256': '44d173288932160d44e5bf7e99e53887b364e64b62e9d1b01978787f0a7c36fc', 'data': ''}, {'path': '/marimo/domains/menu_planning/scripts/minimal_pairs/prepare_assets.py', 'sha256': 'de92dcca87fe6fbab555db70c35f2f9423e239acd3586da5f5ab23dab3865df8', 'data': ''}, {'path': '/marimo/domains/menu_planning/scripts/minimal_pairs/job_supervisor.py', 'sha256': '5def3411ff023bed71fd4063d0e569f4c1226c774a948fbdf1c8aaee5ca44027', 'data': ''}]:
    path = Path(item['path'])
    data = gzip.decompress(base64.b64decode(item['data']))
    assert hashlib.sha256(data).hexdigest() == item['sha256']
    if path.exists():
        assert path.read_bytes() == data, 'Existing destination differs; never overwrite'
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open('xb') as f: f.write(data)
    print(json.dumps({'path': str(path), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'bytes': len(data)}))
